/*------------------[AUTOSAR module version check]--------------------------*/
/**
 * Macro for checking the consistency of AUTOSAR Spec versions of the
 * different files of the ICU module
 */
/* PRQA S 3453 10 *//* Reason for disabling: Implementation often uses macro like function. */
#define ICU_AR_VERSION_CHECK(                                                     \
     file_ar_release_major_version,                                               \
     file_ar_release_minor_version,                                               \
     file_ar_release_revision_version                                             \
     )                                                                            \
     (                                                                            \
        ((ICU_AR_RELEASE_MAJOR_VERSION) == (file_ar_release_major_version)) &&    \
        ((ICU_AR_RELEASE_MINOR_VERSION) == (file_ar_release_minor_version)) &&    \
        ((ICU_AR_RELEASE_REVISION_VERSION) == (file_ar_release_revision_version)) \
     )

/**
 * Macro for checking the consistency of Module ID and Vendor ID
 */
/* This deviation is due to use of code block as macro function */
/* because of being used from pre-processor.                    */
/* PRQA S 3453 7 *//* Reason for disabling: Implementation often uses macro like function. */
#define ICU_EXTRA_CHECK(                       \
    module_id,vendor_id                        \
    )                                          \
    (                                          \
        ((ICU_MODULE_ID) == (module_id)) &&    \
        ((ICU_VENDOR_ID) == (vendor_id))       \
    )

/**
 * Macro for checking the consistency of software versions of the
 * different files of the ICU module
 */
/* PRQA S 3453 10 *//* Reason for disabling: Implementation often uses macro like function. */
#define ICU_SW_VERSION_CHECK(                                                     \
     file_sw_major_version,                                                       \
     file_sw_minor_version,                                                       \
     file_sw_patch_version                                                        \
     )                                                                            \
     (                                                                            \
        ((ICU_SW_MAJOR_VERSION) == (file_sw_major_version)) &&                    \
        ((ICU_SW_MINOR_VERSION) == (file_sw_minor_version)) &&                    \
        ((ICU_SW_PATCH_VERSION) >= (file_sw_patch_version))                       \
     )


